  1313					if (first) {
  1314						first = 0;
  1315					} else {
  1316						smart_str_appends(str, ", ");
  1317					}
  1318					if (key) {
  1319						smart_str_appendc(str, '\'');
  1320						zend_ast_export_str(str, key);
  1321						smart_str_appends(str, "' => ");
  1322					} else {
  1323						smart_str_append_long(str, idx);
  1324						smart_str_appends(str, " => ");
  1325					}
  1326					zend_ast_export_zval(str, val, 0, indent);
  1327				} ZEND_HASH_FOREACH_END();
  1328				smart_str_appendc(str, ']');
  1329				break;
  1330			case IS_CONSTANT_AST:
  1331				zend_ast_export_ex(str, Z_ASTVAL_P(zv), priority, indent);
