  1283		int first;
  1284	
  1285		ZVAL_DEREF(zv);
  1286		switch (Z_TYPE_P(zv)) {
  1287			case IS_NULL:
  1288				smart_str_appends(str, "null");
  1289				break;
  1290			case IS_FALSE:
  1291				smart_str_appends(str, "false");
  1292				break;
  1293			case IS_TRUE:
  1294				smart_str_appends(str, "true");
  1295				break;
  1296			case IS_LONG:
  1297				smart_str_append_long(str, Z_LVAL_P(zv));
  1298				break;
  1299			case IS_DOUBLE:
  1300				key = zend_strpprintf(0, "%.*G", (int) EG(precision), Z_DVAL_P(zv));
  1301				smart_str_appendl(str, ZSTR_VAL(key), ZSTR_LEN(key));
  1302				zend_string_release_ex(key, 0);
  1303				break;
  1304			case IS_STRING:
  1305				smart_str_appendc(str, '\'');
  1306				zend_ast_export_str(str, Z_STR_P(zv));
